#pragma once

#include <esp_now.h>
#include <WiFi.h>
#include "robot_context.h"

void OnDataSent(const uint8_t* mac, esp_now_send_status_t status);
void OnDataRecv(const uint8_t* mac, const uint8_t* incomingData, int len);
bool send_feedback(RobotContext& r);
void handle_feedback(RobotContext& r, bool enabled);
void parse_data(RobotContext& r);

#include "communication.h"
#include "sensor.h"

void OnDataSent(const uint8_t* mac, esp_now_send_status_t status) {
    robot.last_send_status = status;
    if (status == ESP_NOW_SEND_SUCCESS) {
        robot.fail_streak = 0;
    } else if (robot.fail_streak < 255) {
        robot.fail_streak++;
    }
}

void OnDataRecv(const uint8_t* mac, const uint8_t* incomingData, int len) {
    memcpy(&robot.data_received, incomingData, sizeof(robot.data_received));
    if (robot.data_received.password != ROBOT_PASSWORD) {
        return;
    }
    robot.first_mark = millis();
    strcpy(robot.commands, robot.data_received.message);
    robot.new_data = true;
}

bool send_feedback(RobotContext& r) {
    r.data_feedback.password = FB_PASSWORD;
    r.data_feedback.rssi     = r.rssi;
    r.data_feedback.id       = r.robot_id;
    r.data_feedback.battery  = read_battery();

    esp_err_t e = esp_now_send(r.mac_feedback, (uint8_t*)&r.data_feedback, sizeof(r.data_feedback));
    if (e != ESP_OK) {
        if (r.fail_streak < 255) {
            r.fail_streak++;
        }
        return false;
    }
    return true;
}

void handle_feedback(RobotContext& r, bool enabled) {
    if (!enabled) {
        r.paused      = false;
        r.fail_streak = 0;
        return;
    }

    const uint32_t now = millis();

    if (!r.paused && r.fail_streak >= MAX_FAILS_BEFORE_PAUSE) {
        r.paused         = true;
        r.pause_until_ms = now + PAUSE_COOLDOWN_MS;
    }

    if (!r.paused) {
        if (now - r.last_feedback_ms >= FEEDBACK_PERIOD_MS) {
            if (send_feedback(r)) {
                r.last_feedback_ms = now;
            }
        }
        return;
    }

    if (now >= r.pause_until_ms) {
        if (now - r.last_probe_ms >= PROBE_PERIOD_MS) {
            if (send_feedback(r)) {
                r.last_probe_ms = now;
            }
            if (r.last_send_status == ESP_NOW_SEND_SUCCESS) {
                r.paused      = false;
                r.fail_streak = 0;
                r.last_feedback_ms = now;
            }
        }
    }
}

void parse_data(RobotContext& r) {
    char* strtokIndx;
    strtokIndx = strtok(r.temp_chars, ",");

    while (strtokIndx != NULL) {
        r.id = atoi(strtokIndx);

        if (r.id == r.robot_id) {
            r.new_data = false;
            r.stop = false;

            strtokIndx = strtok(NULL, ",");
            r.v_l = atof(strtokIndx);
            strtokIndx = strtok(NULL, ",");
            r.v_a = atof(strtokIndx);
            strtokIndx = strtok(NULL, ",");
            r.th = atof(strtokIndx);
            strtokIndx = strtok(NULL, ",");
            if (!r.waiting_to_kick) {
                r.kick_time = atof(strtokIndx);
            }
            strtokIndx = strtok(NULL, ",");
        } else {
            strtokIndx = strtok(NULL, ",");
            strtokIndx = strtok(NULL, ",");
            strtokIndx = strtok(NULL, ",");
            strtokIndx = strtok(NULL, ",");
            strtokIndx = strtok(NULL, ",");
        }
    }
}

