#pragma once

#include <cstdint>
#include "robot_context.h"

void setup_kicker();
void charge_on(RobotContext& r);
void charge_off(RobotContext& r);
bool can_kick_now(RobotContext& r);
uint32_t calc_power(int pot);
bool do_kick(uint32_t pulse_us);
void kicker_control(RobotContext& r);

#include <Arduino.h>
#include "kicker.h"

void setup_kicker() {
    pinMode(KICKER_PIN, OUTPUT);
    pinMode(CHARGE_KICKER_PIN, OUTPUT);
    digitalWrite(KICKER_PIN, LOW);
    digitalWrite(CHARGE_KICKER_PIN, LOW);
    charge_on(robot);
}

void charge_on(RobotContext& r) {
    if (!r.charge_enabled) {
        digitalWrite(CHARGE_KICKER_PIN, HIGH);
        r.charge_enabled = true;
        r.charge_on_since_ms = millis();
    }
}

void charge_off(RobotContext& r) {
    if (r.charge_enabled) {
        digitalWrite(CHARGE_KICKER_PIN, LOW);
        r.charge_enabled = false;
    }
}

bool can_kick_now(RobotContext& r) {
    unsigned long now = millis();
    if (!r.charge_enabled) return false;
    if (now - r.charge_on_since_ms < MIN_CHARGE_TIME_MS) return false;
    return true;
}

uint32_t calc_power(int pot) {
    return (uint32_t)max(0, min(20000, (int)map(pot, 0, 9, 0, 20000)));
}

bool do_kick(uint32_t pulse_us) {
    digitalWrite(KICKER_PIN, HIGH);
    delayMicroseconds(pulse_us);
    digitalWrite(KICKER_PIN, LOW);
    return true;
}

void kicker_control(RobotContext& r) {
    unsigned long now = millis();

    if (r.waiting_before_recharge) {
        if (now - r.kick_done_ms >= TIME_BEFORE_CHARGE) {
            if (!r.charge_enabled) {
                charge_on(r);
            }
            r.waiting_before_recharge = false;
        }
        return;
    }

    if (r.kick_time <= 0) {
        if (!r.charge_enabled) {
            charge_on(r);
        }
        r.waiting_to_kick = false;
        return;
    }

    if (!r.waiting_to_kick) {
        if (can_kick_now(r)) {
            charge_off(r);
            r.can_kick_since = now;
            r.waiting_to_kick = true;
        }
        return;
    }

    if (now - r.can_kick_since >= TIME_AFTER_CHARGE) {
        if (do_kick(calc_power(r.kick_time))) {
            r.kick_time = 0;
            r.waiting_to_kick = false;
            r.waiting_before_recharge = true;
            r.kick_done_ms = now;
        }
    }
}

#pragma once

#include <esp_wifi.h>

float read_battery();
void promiscuous_rx_cb(void* buff, wifi_promiscuous_pkt_type_t type);

#include "sensor.h"
#include "robot_context.h"
#include "types.h"

float read_battery() {
    int adc_read = analogRead(VOLTAGE_SENSOR_PIN);
    float voltage = adc_read * 0.00511f;
    return voltage;
}

void promiscuous_rx_cb(void* buff, wifi_promiscuous_pkt_type_t type) {
    if (type != WIFI_PKT_MGMT) {
        return;
    }

    const wifi_promiscuous_pkt_t* ppkt = (wifi_promiscuous_pkt_t*)buff;
    const wifi_ieee80211_packet_t* ipkt = (wifi_ieee80211_packet_t*)ppkt->payload;
    const wifi_ieee80211_mac_hdr_t* hdr = &ipkt->hdr;

    bool is_from_station = true;
    for (int i = 0; i < 6; i++) {
        if (hdr->addr2[i] != robot.mac_station[i]) {
            is_from_station = false;
            break;
        }
    }

    if (is_from_station) {
        robot.rssi = ppkt->rx_ctrl.rssi;
    }
}

