#pragma once

#include "robot_context.h"

void send_power(float m1, float m2, float m3, float m4);
float calculate_motor(float v_x, float v_y, float angular, float L, float radius, int motor);
float acceleration(float m, float previous_m, float vel_step, float dt);
void motors_control(RobotContext& r);
void fail_safe(RobotContext& r);

#include <Arduino.h>
#include "speed_control.h"
#include "kicker.h"

void send_power(float m1, float m2, float m3, float m4) {
    String result = "<0," + String(m1) + "," + String(m2) + ","
                  + "1," + String(m3) + "," + String(m4) + ">";
    Serial.println(result);
}

float calculate_motor(float v_x, float v_y, float angular, float L, float radius, int motor) {
    float vel = 0.0f;

    if (motor == 1) {
        vel = (2.0f * L * angular - sqrt(3.0f) * v_x + v_y) / (2.0f * radius);
    }
    if (motor == 2) {
        vel = (sqrt(2.0f) * L * angular - v_x - v_y) / (sqrt(2.0f) * radius);
    }
    if (motor == 3) {
        vel = (sqrt(2.0f) * L * angular + v_x - v_y) / (sqrt(2.0f) * radius);
    }
    if (motor == 4) {
        vel = (2.0f * L * angular + sqrt(3.0f) * v_x + v_y) / (2.0f * radius);
    }

    return vel;
}

float acceleration(float m, float previous_m, float vel_step, float dt) {
    float rate = abs(m - previous_m) / dt;

    if (rate > vel_step) {
        if (m > previous_m) {
            m = previous_m + (vel_step * dt);
        } else {
            m = previous_m - (vel_step * dt);
        }
    }
    return m;
}

void motors_control(RobotContext& r) {
    float vel_rd = calculate_motor(r.v_l, r.v_a, r.th, r.L, r.r, 1);
    float vel_rt = calculate_motor(r.v_l, r.v_a, r.th, r.L, r.r, 2);
    float vel_ld = calculate_motor(r.v_l, r.v_a, r.th, r.L, r.r, 3);
    float vel_lt = calculate_motor(r.v_l, r.v_a, r.th, r.L, r.r, 4);

    vel_rd = acceleration(vel_rd, r.prev_rd, r.vel_step, r.dt);
    vel_rt = acceleration(vel_rt, r.prev_rt, r.vel_step, r.dt);
    vel_ld = acceleration(vel_ld, r.prev_ld, r.vel_step, r.dt);
    vel_lt = acceleration(vel_lt, r.prev_lt, r.vel_step, r.dt);

    send_power(vel_rd, vel_rt, vel_ld, vel_lt);

    r.prev_rd = vel_rd;
    r.prev_rt = vel_rt;
    r.prev_ld = vel_ld;
    r.prev_lt = vel_lt;
}

void fail_safe(RobotContext& r) {
    r.v_l = 0.0f;
    r.v_a = 0.0f;
    r.th = 0.0f;
    r.last_error = 0;
    r.error_sum = 0.0f;
