    char* strtokIndx;
    strtokIndx = strtok(robot.temp_chars, ",");

    while (strtokIndx != NULL) {
        robot.id = atoi(strtokIndx);

        if (robot.id == robot.robot_id) {
            robot.new_data = false;
            robot.stop = false;

            strtokIndx = strtok(NULL, ",");
            robot.v_l = atof(strtokIndx);
            strtokIndx = strtok(NULL, ",");
