#pragma once

#include <cstdint>
#include <cstring>
#include <esp_now.h>
#include "config.h"
#include "types.h"

class RobotContext {
public:
    int robot_id;
    bool use_feedback;
    bool compute_rssi;
    uint8_t mac_feedback[6];
    uint8_t mac_station[6];
    float wheelbase;
    float wheel_radius;
    float vel_step;

    char command_buffer[MESSAGE_LENGTH_BYTES] = {};
    char scratch_buffer[MESSAGE_LENGTH_BYTES] = {};

    int parsed_id = 0;
    bool new_data = false;
    bool stop = false;
    float v_linear = 0.0f;
    float v_angular = 0.0f;
    float throttle = 0.0f;
    int kick_time = 0;
    bool waiting_to_kick = false;

    int last_command_ms = 0;
    float dt = 0.0f;
    int last_time = 0;

    uint32_t last_feedback_ms = 0;
    uint32_t last_probe_ms = 0;
    uint32_t pause_until_ms = 0;
    bool paused = false;
    int fail_streak = 0;

    struct_data          data_received = {};
    struct_feedback      data_feedback = {};
    esp_now_peer_info_t  peer = {};
    esp_now_send_status_t last_send_status = ESP_NOW_SEND_FAIL;

    bool charge_enabled = false;
    unsigned long charge_on_since_ms = 0;
    unsigned long can_kick_since = 0;
    unsigned long kick_done_ms = 0;
    bool waiting_before_recharge = false;

    float prev_rd = 0.0f;
    float prev_rt = 0.0f;
    float prev_ld = 0.0f;
    float prev_lt = 0.0f;

    int last_error = 0;
    float error_sum = 0.0f;

    int32_t rssi = 0;

    RobotContext(int id,
                 bool fb,
                 bool rssi_en,
                 const uint8_t mac_fb[6],
                 const uint8_t mac_st[6],
                 float wbase,
                 float wradius,
                 float step)
        : robot_id(id)
        , use_feedback(fb)
        , compute_rssi(rssi_en)
        , wheelbase(wbase)
        , wheel_radius(wradius)
        , vel_step(step)
    {
        memcpy(mac_feedback, mac_fb, 6);
        memcpy(mac_station, mac_st, 6);
    }
};

extern RobotContext* robot;

#pragma once

#include <esp_now.h>
#include <WiFi.h>
#include "robot_context.h"

void OnDataSent(const uint8_t* mac, esp_now_send_status_t status);
void OnDataRecv(const uint8_t* mac, const uint8_t* incomingData, int len);
bool send_feedback();
void handle_feedback();
void parse_data();

#pragma once

void send_power(float m1, float m2, float m3, float m4);
float calculate_motor(float v_x, float v_y, float angular, float L, float radius, int motor_index);
float ramp_velocity(float target, float previous, float vel_step, float dt);
void motors_control();
void fail_safe();

#include <Arduino.h>
#include "communication.h"
#include "sensor.h"

void OnDataSent(const uint8_t *mac, esp_now_send_status_t status)
{
    robot->last_send_status = status;
    if (status == ESP_NOW_SEND_SUCCESS) {
        robot->fail_streak = 0;
    } else if (robot->fail_streak < 255) {
        robot->fail_streak++;
    }
}

void OnDataRecv(const uint8_t *mac, const uint8_t *incomingData, int len)
{
    memcpy(&robot->data_received, incomingData, sizeof(robot->data_received));
    if (robot->data_received.password != ROBOT_PASSWORD) {
        return;
    }
    robot->last_command_ms = millis();
    strcpy(robot->command_buffer, robot->data_received.message);
    robot->new_data = true;
}

bool send_feedback()
{
    robot->data_feedback.password = FEEDBACK_PASSWORD;
    robot->data_feedback.rssi     = robot->rssi;
    robot->data_feedback.id       = robot->robot_id;
    robot->data_feedback.battery  = read_battery();

    esp_err_t e = esp_now_send(robot->mac_feedback,
                               (uint8_t *)&robot->data_feedback,
                               sizeof(robot->data_feedback));
    if (e != ESP_OK) {
        if (robot->fail_streak < 255) {
            robot->fail_streak++;
        }
        return false;
    }
    return true;
}

void handle_feedback()
{
    if (!robot->use_feedback) {
        robot->paused      = false;
        robot->fail_streak = 0;
        return;
    }

    const uint32_t now = millis();

    if (!robot->paused && robot->fail_streak >= MAX_FAILS_BEFORE_PAUSE) {
        robot->paused         = true;
        robot->pause_until_ms = now + PAUSE_COOLDOWN_MS;
    }

    if (!robot->paused) {
        if (now - robot->last_feedback_ms >= FEEDBACK_INTERVAL_MS) {
            if (send_feedback()) {
                robot->last_feedback_ms = now;
            }
        }
        return;
    }

    if (now >= robot->pause_until_ms) {
        if (now - robot->last_probe_ms >= PROBE_PERIOD_MS) {
            if (send_feedback()) {
                robot->last_probe_ms = now;
            }
            if (robot->last_send_status == ESP_NOW_SEND_SUCCESS) {
                robot->paused           = false;
                robot->fail_streak      = 0;
                robot->last_feedback_ms = now;
            }
        }
    }
}

void parse_data()
{
    char *strtokIndx;
    strtokIndx = strtok(robot->scratch_buffer, ",");

    while (strtokIndx != NULL) {
        robot->parsed_id = atoi(strtokIndx);

        if (robot->parsed_id == robot->robot_id) {
            robot->stop = false;

            strtokIndx = strtok(NULL, ",");
            robot->v_linear = atof(strtokIndx);
            strtokIndx = strtok(NULL, ",");
            robot->v_angular = atof(strtokIndx);
            strtokIndx = strtok(NULL, ",");
            robot->throttle = atof(strtokIndx);
            strtokIndx = strtok(NULL, ",");
            if (!robot->waiting_to_kick) {
                robot->kick_time = atof(strtokIndx);
            }
            strtokIndx = strtok(NULL, ",");
        } else {
            strtokIndx = strtok(NULL, ",");
            strtokIndx = strtok(NULL, ",");
            strtokIndx = strtok(NULL, ",");
            strtokIndx = strtok(NULL, ",");
            strtokIndx = strtok(NULL, ",");
        }
    }
}

#include <Arduino.h>
#include "speed_control.h"
#include "robot_context.h"
#include "kicker.h"

enum MotorIndex {
    MOTOR_RIGHT_DOWN = 1,
    MOTOR_RIGHT_TOP  = 2,
    MOTOR_LEFT_DOWN  = 3,
    MOTOR_LEFT_TOP   = 4,
};

void send_power(float m1, float m2, float m3, float m4)
{
    String result = "<0," + String(m1) + "," + String(m2) + ","
                  + "1," + String(m3) + "," + String(m4) + ">";
    Serial.println(result);
}

float calculate_motor(float v_x, float v_y, float angular, float L, float radius, int motor_index)
{
    switch (motor_index) {
    case MOTOR_RIGHT_DOWN:
        return (2.0f * L * angular - sqrt(3.0f) * v_x + v_y) / (2.0f * radius);
    case MOTOR_RIGHT_TOP:
        return (sqrt(2.0f) * L * angular - v_x - v_y) / (sqrt(2.0f) * radius);
    case MOTOR_LEFT_DOWN:
        return (sqrt(2.0f) * L * angular + v_x - v_y) / (sqrt(2.0f) * radius);
    case MOTOR_LEFT_TOP:
        return (2.0f * L * angular + sqrt(3.0f) * v_x + v_y) / (2.0f * radius);
    default:
        return 0.0f;
    }
}

float ramp_velocity(float target, float previous, float vel_step, float dt)
{
    float rate = abs(target - previous) / dt;

    if (rate > vel_step) {
        if (target > previous) {
            return previous + (vel_step * dt);
        } else {
            return previous - (vel_step * dt);
        }
    }
    return target;
}

void motors_control()
{
    float vel_rd = calculate_motor(robot->v_linear, robot->v_angular, robot->throttle,
                                    robot->wheelbase, robot->wheel_radius, MOTOR_RIGHT_DOWN);
    float vel_rt = calculate_motor(robot->v_linear, robot->v_angular, robot->throttle,
                                    robot->wheelbase, robot->wheel_radius, MOTOR_RIGHT_TOP);
    float vel_ld = calculate_motor(robot->v_linear, robot->v_angular, robot->throttle,
                                    robot->wheelbase, robot->wheel_radius, MOTOR_LEFT_DOWN);
    float vel_lt = calculate_motor(robot->v_linear, robot->v_angular, robot->throttle,
                                    robot->wheelbase, robot->wheel_radius, MOTOR_LEFT_TOP);

    vel_rd = ramp_velocity(vel_rd, robot->prev_rd, robot->vel_step, robot->dt);
    vel_rt = ramp_velocity(vel_rt, robot->prev_rt, robot->vel_step, robot->dt);
    vel_ld = ramp_velocity(vel_ld, robot->prev_ld, robot->vel_step, robot->dt);
    vel_lt = ramp_velocity(vel_lt, robot->prev_lt, robot->vel_step, robot->dt);

    send_power(vel_rd, vel_rt, vel_ld, vel_lt);

    robot->prev_rd = vel_rd;
    robot->prev_rt = vel_rt;
    robot->prev_ld = vel_ld;
    robot->prev_lt = vel_lt;
}

void fail_safe()
{
    robot->v_linear  = 0.0f;
    robot->v_angular = 0.0f;
    robot->throttle  = 0.0f;
    robot->last_error = 0;
    robot->error_sum  = 0.0f;
    robot->stop       = true;

    robot->kick_time      = 0;
    robot->waiting_to_kick = false;
    charge_off();
}

#include <WiFi.h>
#include "robot_context.h"
#include "communication.h"
#include "kicker.h"
#include "sensor.h"
#include "speed_control.h"

RobotContext* robot = nullptr;

void setup()
{
    const uint8_t mac_fb[6] = {0xA4, 0xCF, 0x12, 0x72, 0xB7, 0x20};
    const uint8_t mac_st[6] = {0x08, 0xB6, 0x1F, 0x28, 0xE3, 0x94};
    robot = new RobotContext(2, true, true, mac_fb, mac_st, 0.0785f, 0.03f, 100.0f);

    Serial.begin(115200);
    WiFi.mode(WIFI_STA);

    pinMode(2, OUTPUT);
    pinMode(VOLTAGE_SENSOR_PIN, INPUT);

    setup_kicker();

    if (esp_now_init() != ESP_OK) {
        Serial.println("Error initializing ESP-NOW");
        ESP.restart();
        return;
    }

    robot->peer.channel = 0;
    robot->peer.encrypt = false;
    memcpy(robot->peer.peer_addr, robot->mac_feedback, 6);
    if (esp_now_add_peer(&robot->peer) != ESP_OK) {
        Serial.println("Failed to add peer");
        ESP.restart();
    }

    esp_now_register_recv_cb(OnDataRecv);
    esp_now_register_send_cb(OnDataSent);

    esp_wifi_set_promiscuous(robot->compute_rssi);
    if (robot->compute_rssi) {
        esp_wifi_set_promiscuous_rx_cb(&promiscuous_rx_cb);
    }
}

void loop()
{
    strcpy(robot->scratch_buffer, robot->command_buffer);

    bool incoming = robot->new_data;
    if (incoming) {
        parse_data();
        robot->new_data = false;
    }

    int now_ms = millis();
    if (now_ms - robot->last_command_ms > FAILSAFE_MS) {
        fail_safe();
    }

    kicker_control();

    int crt = millis();
    robot->dt = (crt - robot->last_time) / 1000.0f;
    robot->last_time = crt;

    if (!robot->stop) {
        motors_control();
    }

    handle_feedback();
}

