    }

    int now_ms = millis();
    if (now_ms - robot->last_command_ms > FAILSAFE_MS) {
        fail_safe();
    }

    kicker_control();

    int crt = millis();
    robot->dt = (crt - robot->last_time) / 1000.0f;
    robot->last_time = crt;

    if (!robot->stop) {
        motors_control();
    }

    handle_feedback();
}
```

This is clean and readable. Each block does one thing.

